import pytest
from typing import List, Optional

def process_list(items: List[int]) -> int:
    """Sum positive numbers in a list."""
    if not items:
        return 0
    return sum(x for x in items if x > 0)

class TestEdgeCases:
    """EGRR_PATTERN: Edge case testing patterns."""

    # Empty inputs
    def test_empty_list(self):
        assert process_list([]) == 0

    def test_none_like_behavior(self):
        # If function accepts None, test it
        with pytest.raises(TypeError):
            process_list(None)

    # Single element
    def test_single_positive_element(self):
        assert process_list([5]) == 5

    def test_single_negative_element(self):
        assert process_list([-5]) == 0

    def test_single_zero_element(self):
        assert process_list([0]) == 0

    # Boundary values
    def test_all_zeros(self):
        assert process_list([0, 0, 0]) == 0

    def test_all_negatives(self):
        assert process_list([-1, -2, -3]) == 0

    def test_all_positives(self):
        assert process_list([1, 2, 3]) == 6

    def test_mixed_values(self):
        assert process_list([-1, 0, 1, 2, -2]) == 3

    # Large inputs
    def test_large_list(self):
        large_list = list(range(10000))
        assert process_list(large_list) == sum(range(1, 10000))

    def test_large_values(self):
        assert process_list([10**9, 10**9]) == 2 * 10**9

    # Type edge cases
    @pytest.mark.parametrize("invalid_input", [
        "not a list",
        {1, 2, 3},
        {"a": 1},
        123,
    ])
    def test_invalid_types_raise_error(self, invalid_input):
        """EGRR_PATTERN: Test invalid input types."""
        with pytest.raises((TypeError, AttributeError)):
            process_list(invalid_input)
